/**
 * Friend type
 */
declare enum DirectionType {
    /**
     * Two-way friend
     */
    BOTH = 2
}
/**
 * Query interface - Friend type
 */
declare enum QueryFriendsDirectionType {
    /**
     * Two-way friend
     */
    BOTH = 2
}
/**
 * Friend adding permission
 */
declare enum FriendAddPermission {
    /**
     * Allow anyone to add friend.
     */
    FREE = 1,
    /**
     * Requires user consent to add a friend.
     */
    NEED_VERIFY = 2,
    /**
     * Prohibits anyone from adding friends
     */
    NO_ONE_ALLOWED = 3
}
/**
 * Friend relationship type
 */
declare enum FriendRelationType {
    /**
     * Not friends, not in each other's friend lists
     */
    NONE = 0,
    /**
     * Only if the other party is in my friend list
     */
    IN_MY_FRIEND_LIST = 1,
    /**
     * Only I am in the other party's friend list.
     */
    IN_OTHER_FRIEND_LIST = 2,
    /**
     * Two-way friend, present in each other's friend lists.
     */
    BOTH_WAY = 3
}
/**
 * Friend request type
 */
declare enum FriendApplicationType {
    /**
     * Sent adding friend request
     */
    SENT = 1,
    /**
     * Received adding friend request
     */
    RECEIVED = 2
}
/**
 * Friend request status
 */
declare enum FriendApplicationStatus {
    /**
     * Request to add a friend
     */
    UNHANDLED = 0,
    /**
     * Accepted
     */
    ACCEPTED = 1,
    /**
     * Rejected, declined friend requests from others.
     */
    REFUSED = 2,
    /**
     * Expired
     */
    EXPIRED = 3
}

/**
 * Active join group permission verification method
 */
declare enum GroupJoinPermission {
    /**
     * Requires group owner verification (Default)
     */
    OWNER_VERIFY = 0,
    /**
     * Authentication not required
     */
    FREE = 1,
    /**
     * Group administrator or group owner verification
     */
    OWNER_OR_MANAGER_VERIFY = 2,
    /**
     * No one is allowed to join.
     */
    NO_ONE_ALLOWED = 3
}
/**
 * Group operation permissions
 */
declare enum GroupOperationPermission {
    /**
     * Group owner (Default)
     */
    OWNER = 0,
    /**
     * Group owner or group administrator
     */
    OWNER_OR_MANAGER = 1,
    /**
     * Everyone
     */
    EVERYONE = 2
}
/**
 * Group member information editing permissions
 */
declare enum GroupMemberInfoEditPermission {
    /**
     * Group owner + group administrator + self (Default)
     */
    OWNER_OR_MANAGER_OR_SELF = 0,
    /**
     * Group owner + myself
     */
    OWNER_OR_SELF = 1,
    /**
     * Only myself
     */
    SELF = 2
}
/**
 * Group invitation verification method
 */
declare enum GroupInviteHandlePermission {
    /**
     * Join the group directly (Default).
     */
    FREE = 0,
    /**
     * Requires invitee's consent.
     */
    INVITEE_VERIFY = 1
}
/**
 * Group member role
 */
declare enum GroupMemberRole {
    /**
     * Role-independent or unknown role
     */
    UNDEF = 0,
    /**
     * Regular group member
     */
    NORMAL = 1,
    /**
     * Administrator
     */
    MANAGER = 2,
    /**
     * Group owner
     */
    OWNER = 3
}
/**
 * Group operations
 */
declare enum GroupOperation {
    /**
     * Create
     */
    CREATE = 0,
    /**
     * Join
     */
    JOIN = 1,
    /**
     * Kick out
     */
    KICK = 2,
    /**
     * Quit
     */
    QUIT = 3,
    /**
     * Dismiss
     */
    DISMISS = 4,
    /**
     * Add as administrator
     */
    ADD_MANAGER = 5,
    /**
     * Remove from administrator
     */
    REMOVE_MANAGER = 6,
    /**
     * Transfer group ownership
     */
    TRANSFER_GROUP_OWNER = 7
}
/**
 * Group operation type
 */
declare enum GroupOperationType {
    /**
     * Add
     */
    ADD = 1,
    /**
     * Remove
     */
    REMOVE = 2
}
/**
 * Group request status
 */
declare enum GroupApplicationStatus {
    /**
     * Waiting for administrator approval
     */
    MANAGER_UNHANDLED = 0,
    /**
     * Administrator has rejected
     */
    MANAGER_REFUSED = 1,
    /**
     * Waiting for the invitee to respond
     */
    INVITEE_UNHANDLED = 2,
    /**
     * The invitee declined
     */
    INVITEE_REFUSED = 3,
    /**
     * Joined
     */
    JOINED = 4,
    /**
     * Expired
     */
    EXPIRED = 5
}
declare enum GroupOperationStatus {
    REFUSE = 0,
    ACCEPT = 1
}
declare enum GroupOperationRole {
    APPLICANT = 0,
    MANAGER = 1
}
/**
 * Request type
 */
declare enum GroupApplicationType {
    /**
     * Actively join a group.
     */
    APPLICATION = 0,
    /**
     * Invited to join a group.
     */
    INVITATION = 1
}
/**
 * Group request direction
 */
declare enum GroupApplicationDirection {
    /**
     * Submit application.
     */
    APPLICATION_SENT = 0,
    /**
     * Sent invitation.
     */
    INVITATION_SENT = 1,
    /**
     * Received invitation.
     */
    INVITATION_RECEIVED = 2,
    /**
     * Received application.
     */
    APPLICATION_RECEIVED = 3
}

/**
 * Chatroom KV storage operation type.
 * The other party's operation will include this value in the message received by the local user (RC:chrmKVNotiMsg).
 * Use this value to determine whether it is a deletion or an update.
 */
declare enum ChatroomEntryType {
    /**
     * Update
     */
    UPDATE = 1,
    /**
     * Delete
     */
    DELETE = 2
}

/**
 * The status in messages during multi-device synchronization in chatrooms: Join/Leave
 */
declare enum ChrmSyncStatus {
    /**
     * Quit
     */
    QUIT = 0,
    /**
     * Join
     */
    JOIN = 1
}

/**
 * Reasons for leaving a chatroom during multi-device synchronization
 */
declare enum ChatroomSyncStatusReason {
    /**
     * Left voluntarily
     */
    LeaveOnMyOwn = 1,
    /**
     * Kicked out due to multi-device login conflict
     */
    OtherDeviceLogin = 2
}

/**
 * Chatroom member entry and exit status
 */
declare enum ChatroomUserChangeType {
    QUIT = 0,
    JOIN = 1
}

/**
 * Chatroom Mute/Unmute enum type
 */
declare enum ChrmMemBanType {
    /**
     * Unmute one or more users in the specified chatroom.
     */
    UnmuteUsers = 0,
    /**
     * Mute one or more users in the specified chatroom.
     */
    MuteUsers = 1,
    /**
     * Unmute all users in the specified chatroom.
     */
    UnmuteAll = 2,
    /**
     * Mute all users in the specified chatroom.
     */
    MuteAll = 3,
    /**
     * Remove users from the mute whitelist.
     */
    RemoveWhitelist = 4,
    /**
     * Add users to the mute whitelist.
     */
    AddWhitelist = 5,
    /**
     * Remove users from the global mute blacklist.
     */
    UnmuteGloble = 6,
    /**
     * Add users to the global mute blacklist.
     */
    MuteGloble = 7
}

/**
 * Unban/Ban users from sending messages in the chatroom, enum type.
 */
declare enum ChrmMemOperateType {
    /**
     * Unban
     */
    Deblock = 0,
    /**
     * Ban
     */
    Blocked = 1
}

